// AI pre-translation of Realchecker FE keys carrying TAG that are still empty in a language (reusable).
// Runs: 14 Oct 2026 (image lookup, by creation day), 21 Oct 2026 (tag 211026, 155 keys), 26 Oct 2026 (tag 261026, 6 keys x 22 langs, FINAL set, exec 907687), 28 Oct 2026 (tag REALCHECK-477: 9 keys x 22 langs = 198 written as unverified + AI_TO_REVIEW, reviewed FINAL set, check exec 921175, write exec 921187; resubscribe_description excluded, translated by Kseniya).
// Keep MODE 'check'; switch to 'write' deliberately for a run, then back. FINAL (optional): reviewed {iso:{key_id:text}} written instead of the fresh model output; leave empty for normal runs.
// EXCLUDE: key ids carrying TAG that must not be translated in this run (they stay in the corpus as TM).
const MODE = 'check';
const LANGS = ['cs', 'da', 'de', 'el', 'es', 'fr', 'hr', 'id', 'it', 'ko', 'ms', 'nl', 'no', 'pl', 'pt', 'ro', 'sk', 'sv', 'th', 'tr', 'uk', 'vi'];
const TAG = 'REALCHECK-477';
const CHUNK = 40;
const BATCH = "";
const NOTES = "";
const ANCHORS = [];
const DESCS = {};
const FINAL = {};
const FINAL_EN = {};
const EXCLUDE = [];
return [{ json: { mode: MODE, langs: LANGS, tag: TAG, chunk: CHUNK, batch: BATCH, notes: NOTES, anchors: ANCHORS, descs: DESCS, final: FINAL, final_en: FINAL_EN, exclude: EXCLUDE } }];

const cfg = $('Config').first().json;
const NAME = { cs: /czech/i, da: /danish/i, de: /german/i, el: /greek/i, es: /spanish/i, fr: /french/i, hr: /croatian/i, id: /indonesian/i, it: /italian/i, ko: /korean/i, ms: /malay/i, nl: /dutch/i, no: /norwegian/i, pl: /polish/i, pt: /portuguese/i, ro: /romanian/i, sk: /slovak/i, sv: /swedish/i, th: /thai/i, tr: /turkish/i, uk: /ukr/i, vi: /vietnamese/i };
const files = (($input.first().json || {}).files) || [];
const out = [];
for (const iso of cfg.langs) {
  const rx = NAME[iso];
  const cand = files.filter(function (f) { return rx && rx.test(String(f.name || '')) && /style guide/i.test(String(f.name || '')); })
    .sort(function (a, b) { return String(b.modifiedTime).localeCompare(String(a.modifiedTime)); });
  if (cand.length) { out.push({ json: { iso: iso, name: cand[0].name, url: 'https://www.googleapis.com/drive/v3/files/' + cand[0].id + '/export?mimeType=text%2Fplain' } }); }
}
if (!out.length) { out.push({ json: { iso: '__none__', name: '', url: 'https://www.googleapis.com/drive/v3/about?fields=user' } }); }
return out;

const b = $input.first().json.body || $input.first().json;
if (!Array.isArray(b.projects)) { throw new Error('projects fetch failed'); }
const re = /(real ?checker|vin checker|mobitrace)/i;
return b.projects.filter(function (p) { return re.test(p.name) && !/html|legal/i.test(p.name); })
  .map(function (p) { return { json: { pid: p.project_id, name: p.name, url: 'https://api.lokalise.com/api2/projects/' + p.project_id + '/keys?include_translations=1&disable_references=1&filter_archived=exclude&limit=500&pagination=cursor' } }; });

// Builds one OpenAI request per (language, chunk of keys). Read-only. Targets: Realchecker FE keys carrying cfg.tag (minus cfg.exclude).
const cfg = $('Config').first().json;
const FE = '964775386a3ce03ecca883.03770715';
const LN = { cs: 'Czech', da: 'Danish', de: 'German', el: 'Greek', es: 'Spanish', fr: 'French', hr: 'Croatian', id: 'Indonesian', it: 'Italian', ko: 'Korean', ms: 'Malay', nl: 'Dutch', no: 'Norwegian (Bokmål)', pl: 'Polish', pt: 'Brazilian Portuguese (pt-BR)', ro: 'Romanian', sk: 'Slovak', sv: 'Swedish', th: 'Thai', tr: 'Turkish', uk: 'Ukrainian', vi: 'Vietnamese' };
const ISO_BY_ID = { 765: 'cs', 767: 'da', 666: 'de', 761: 'el', 640: 'en', 1056: 'es', 673: 'fr', 793: 'hr', 757: 'id', 734: 'it', 733: 'ko', 749: 'ms', 737: 'nl', 760: 'no', 759: 'no', 748: 'pl', 708: 'pt', 770: 'ro', 799: 'sk', 754: 'sv', 753: 'th', 744: 'tr', 769: 'uk', 774: 'vi' };
function txt(v) { if (v === null || v === undefined || typeof v === 'object') { return ''; } return String(v); }
function kn(k) { const n = k.key_name || {}; return typeof n === 'string' ? n : (n.web || n.other || ''); }
const corpus = []; const targets = [];
const EXC = (cfg.exclude || []).map(Number);
for (const it of $('Fetch corpus').all()) {
  const b = it.json.body || {}; if (!Array.isArray(b.keys)) { continue; }
  for (const k of b.keys) {
    if (k.is_archived) { continue; }
    const tr = {}; let en = '';
    for (const t of (k.translations || [])) { const s = txt(t.translation); if (t.language_iso === 'en') { en = s; } else if (s.trim()) { tr[t.language_iso] = s; } }
    if (!en.trim()) { continue; }
    const row = { id: k.key_id, name: kn(k), pid: b.project_id, en: en, t: tr, d: String(cfg.descs[String(k.key_id)] || k.description || '') };
    if (b.project_id === FE && (k.tags || []).indexOf(cfg.tag) !== -1 && EXC.indexOf(Number(k.key_id)) === -1) { targets.push(row); } else { corpus.push(row); }
  }
}
if (!targets.length) { throw new Error('No target keys found for tag ' + cfg.tag); }
targets.sort(function (a, b) { return a.name.localeCompare(b.name); });
function norm(s) { return String(s).replace(/<[^>]+>/g, ' ').replace(/\[%[^\]]*\]/g, ' X ').replace(/[’‘]/g, "'").replace(/\s+/g, ' ').trim().toLowerCase(); }
function toks(s) { return new Set((norm(s).match(/[\p{L}\p{N}']{2,}/gu) || [])); }
for (const c of corpus) { c.n = norm(c.en); c.w = toks(c.en); }
const byN = {}; for (const c of corpus) { (byN[c.n] = byN[c.n] || []).push(c); }
for (const t of targets) {
  t.n = norm(t.en); const W = toks(t.en); const ex = byN[t.n] || [];
  const fz = [];
  if (W.size >= 2) {
    for (const c of corpus) {
      if (c.n === t.n || !c.w.size) { continue; }
      const r = c.w.size / W.size; if (r < 0.5 || r > 2) { continue; }
      let i = 0; W.forEach(function (x) { if (c.w.has(x)) { i++; } });
      const sc = 2 * i / (W.size + c.w.size);
      if (sc >= 0.6) { fz.push({ c: c, sc: sc }); }
    }
  }
  fz.sort(function (a, b) { return b.sc - a.sc || (a.c.pid === FE ? -1 : 1); });
  t.ex = ex.sort(function (a, b) { return (a.pid === FE ? -1 : 1); }).slice(0, 3);
  t.fz = fz.slice(0, 3);
}
const RULES = {}, JUDGE = {};
for (const it of $('Style rules').all()) { const r = it.json || {}; if (!r.iso || r.iso === '*') { continue; } let l = []; try { l = JSON.parse(r.rules_json || '[]'); } catch (e) { } RULES[r.iso] = l.filter(function (x) { return !x.project || x.project !== 'personality'; }).map(function (x) { return (x.desc || x.id) + (x.suggest ? ' (use: ' + x.suggest + ')' : ''); }); JUDGE[r.iso] = r.judgement || ''; }
const FB = {};
for (const it of $('Feedback').all()) { const r = it.json || {}; if (!r.iso || !r.decision) { continue; } (FB[r.iso] = FB[r.iso] || []).push({ d: r.decision, rule: String(r.rule || '').slice(0, 80), en: String(r.en || '').slice(0, 120), t: String(r.translation || '').slice(0, 120), why: String(r.reason || r.issue || '').slice(0, 160) }); }
const GUIDE = {};
const gp = $('Guide plan').all(); const ge = $('Export guides').all();
for (let i = 0; i < gp.length; i++) { const iso = gp[i].json.iso; const g = ge[i] ? ge[i].json : {}; const s = typeof g.data === 'string' ? g.data : ''; if (s && iso !== '__none__') { GUIDE[iso] = s.replace(/\r/g, '').replace(/\n{3,}/g, '\n\n').slice(0, 24000); } }
let terms = [];
for (const it of $('Glossary').all()) { const b = it.json.body !== undefined ? it.json.body : it.json; terms = terms.concat((b && (b.data || b.glossary_terms || b.terms)) || []); }
function yes(v) { return v === true || v === 1 || String(v).toLowerCase() === 'yes' || String(v).toLowerCase() === 'true'; }
function tagList(t) { const raw = t.tags || []; const arr = Array.isArray(raw) ? raw : String(raw).split(','); return arr.map(function (x) { return String(typeof x === 'object' && x ? (x.name || x.tag || '') : x).trim().toLowerCase(); }).filter(function (x) { return x; }); }
const inScope = terms.filter(function (t) { const tg = tagList(t); return !tg.length || tg.indexOf('shared') !== -1 || tg.indexOf('realchecker') !== -1; });
function esc(s) { return String(s).replace(/[.*+?^${}()|[\]\\]/g, '\\$&'); }
function glossFor(iso, ens) {
  const out = []; const blob = ens.join(' \n ');
  for (const t of inScope) {
    const src = String(t.term || '').trim(); if (!src) { continue; }
    const rx = new RegExp('(?<![\\p{L}\\p{N}])' + esc(src) + '(?![\\p{L}\\p{N}])', 'u' + (yes(t.caseSensitive) ? '' : 'i'));
    if (!rx.test(blob)) { continue; }
    let tgt = '', note = '';
    for (const tr of (t.translations || [])) { const i2 = ISO_BY_ID[tr.langId || tr.lang_id] || (String(tr.langIso || tr.lang_iso || '') === 'pt_BR' ? 'pt' : String(tr.langIso || tr.lang_iso || '')); if (i2 === iso) { tgt = String(tr.translation || '').trim(); note = String(tr.description || '').trim(); } }
    const translatable = t.translatable === undefined ? true : yes(t.translatable);
    if (translatable && !tgt && !yes(t.forbidden)) { continue; }
    out.push({ term: src, target: translatable ? tgt : '(do not translate: keep as is)', forbidden: yes(t.forbidden) || undefined, note: (note || String(t.description || '')).slice(0, 160) || undefined });
  }
  return out;
}
const ANCH = cfg.anchors;
const anchorRows = corpus.filter(function (c) { return c.pid === FE && ANCH.indexOf(c.name) !== -1; });
const NL = String.fromCharCode(10);
const jobs = [];
for (const iso of cfg.langs) {
  const todo = targets.filter(function (t) { return !t.t[iso]; });
  if (!todo.length) { continue; }
  const anchors = anchorRows.filter(function (a) { return a.t[iso]; }).map(function (a) { return { en: a.en, t: a.t[iso], where: a.name }; });
  const fb = (FB[iso] || []).slice(-15);
  for (let c = 0; c < todo.length; c += cfg.chunk) {
    const part = todo.slice(c, c + cfg.chunk);
    const items = part.map(function (t) {
      const tm = [];
      for (const e of t.ex) { if (e.t[iso]) { tm.push({ match: '100% (exact)', en: e.en, translation: e.t[iso] }); } }
      for (const f of t.fz) { if (f.c.t[iso]) { tm.push({ match: 'fuzzy ' + Math.round(f.sc * 100) + '%', en: f.c.en, translation: f.c.t[iso] }); } }
      return { id: String(t.id), key: t.name, en: t.en, context: t.d.slice(0, 900), tm: tm.length ? tm.slice(0, 4) : undefined };
    });
    const SYS = [
      'You are a senior native ' + LN[iso] + ' localizer translating UI strings of RealChecker, a web app for reverse phone, email, VIN and image lookup and phone location. ' + cfg.batch,
      'Translate every item from English into ' + LN[iso] + '. Write natural, idiomatic, concise product copy a native speaker would expect in a polished web app, not a literal rendering.',
      'PRIORITIES, in order: (1) the ' + LN[iso] + ' STYLE GUIDE below (register/formality, tone, typography, number/date/punctuation conventions); (2) the GLOSSARY (use the approved target terms; never use forbidden terms; keep brand names like RealChecker unchanged); (3) TRANSLATION MEMORY: items may carry 100% (exact) matches and fuzzy matches from our approved translations. Reuse a 100% match verbatim unless it breaks the glossary or style guide or does not fit the context. Reuse terminology and phrasing from fuzzy matches so the new pages read like the existing ones. (4) ANCHORS: existing translations of related UI labels; use the same wording for the same concepts.',
      'Read each item\'s context (key description): it says where the text appears, who reads it, length guidance (buttons and labels must stay short), consistency notes (identical English must get identical translations; quoted button labels must match the button keys), and consent wording (translate exactly, no softening).',
      cfg.notes,
      'MECHANICS (strict): keep every placeholder exactly as in the source, e.g. [%1$s:n], [%1$s:phone]; keep tags such as <b>...</b>, <number>...</number> and <br></br> exactly (same count), with the translated text inside; keep the → arrows. Do not add or remove leading/trailing spaces. Square brackets without % (e.g. [your name]) are visible hint text, not placeholders: translate the words inside and keep the brackets.',
      'Translate everything else: do not leave English words untranslated unless they are brand, product, app or OS names (Chrome, Safari, Edge, Firefox, Opera, Samsung Internet, WhatsApp, Mac, Windows, iPhone, iPad, Android), VIN, realchecker.com, or the glossary says to keep them.',
      'Return ONLY JSON: {"t":{"<id>":"<translation>", ...}} keyed by the numeric item id (not the key name), with an entry for EVERY id.',
      '',
      '=== ' + LN[iso] + ' STYLE GUIDE (source of truth) ===',
      GUIDE[iso] ? GUIDE[iso] : '(full guide unavailable; use the rules below)',
      '',
      '=== Style rules distilled by the i18n team ===',
      (RULES[iso] || []).slice(0, 40).join(NL) || '(none)',
      JUDGE[iso] ? ('Judgement notes: ' + JUDGE[iso]) : '',
      fb.length ? ('Reviewer precedent (i18n lead decisions on earlier audits, follow them): ' + JSON.stringify(fb)) : ''
    ].join(NL);
    const user = { language: LN[iso], glossary: glossFor(iso, part.map(function (t) { return t.en; })), anchors: anchors, items: items };
    jobs.push({ json: { iso: iso, chunk: c / cfg.chunk, ids: part.map(function (t) { return t.id; }), guide: !!GUIDE[iso], body: JSON.stringify({ model: 'gpt-4.1', temperature: 0.2, max_tokens: 16000, response_format: { type: 'json_object' }, messages: [{ role: 'system', content: SYS }, { role: 'user', content: JSON.stringify(user) }] }) } });
  }
}
return jobs;

// Parses OpenAI answers, validates mechanics, unifies identical English (any length). Read-only.
const jobs = $('Build jobs').all().map(function (i) { return i.json; });
const res = $input.all().map(function (i) { return i.json || {}; });
function bag(s, rx) { const m = {}; for (const x of (String(s).match(rx) || [])) { m[x] = (m[x] || 0) + 1; } return JSON.stringify(Object.keys(m).sort().map(function (k) { return k + ':' + m[k]; })); }
const PH = /\[%[^\]]*\]/g, TAG = /<\/?[A-Za-z]+>/g;
function check(en, t, key) {
  if (!t || !String(t).trim()) { return 'empty'; }
  const pe = Array.from(new Set(String(en).match(PH) || [])).sort().join('|'), pt = Array.from(new Set(String(t).match(PH) || [])).sort().join('|');
  if (pe !== pt) { return 'placeholder mismatch'; }
  if (bag(en, TAG) !== bag(t, TAG)) { return 'tag mismatch'; }
  if ((String(en).match(/→/g) || []).length !== (String(t).match(/→/g) || []).length) { return 'arrow count changed'; }
  const letters = /\p{L}/u.test(String(en).replace(PH, ''));
  if (letters && String(t).trim() === String(en).trim() && en.split(/\s+/).length >= 4) { return 'untranslated'; }
  if (t !== t.trim() && en === en.trim()) { return 'extra whitespace'; }
  return '';
}
const per = {}; const bad = []; const callErr = [];
for (let i = 0; i < jobs.length; i++) {
  const j = jobs[i]; const r = res[i] || {};
  const items = JSON.parse(JSON.parse(j.body).messages[1].content).items;
  let parsed = null;
  try { parsed = JSON.parse(String(r.choices[0].message.content).replace(/^```json|```$/g, '').trim()).t; } catch (e) { callErr.push({ iso: j.iso, chunk: j.chunk, err: r.error ? JSON.stringify(r.error).slice(0, 200) : String(e.message || e) }); continue; }
  per[j.iso] = per[j.iso] || {};
  for (const it of items) {
    const t = parsed ? (parsed[it.id] !== undefined ? parsed[it.id] : parsed[it.key]) : undefined;
    if (typeof t !== 'string') { bad.push({ iso: j.iso, key: it.key, why: 'missing in answer' }); continue; }
    const why = check(it.en, t, it.key);
    if (why) { bad.push({ iso: j.iso, key: it.key, why: why, en: it.en.slice(0, 200), t: String(t).slice(0, 300) }); continue; }
    per[j.iso][it.id] = { key: it.key, en: it.en, t: t, tm: it.tm ? it.tm[0].match : '' };
  }
}
// identical English -> one translation per language (most frequent wins, then first)
let unified = 0;
for (const iso in per) {
  const groups = {};
  for (const id in per[iso]) { const e = per[iso][id].en.trim(); (groups[e] = groups[e] || []).push(id); }
  for (const e in groups) {
    const ids = groups[e]; if (ids.length < 2) { continue; }
    const cnt = {}; for (const id of ids) { const t = per[iso][id].t; cnt[t] = (cnt[t] || 0) + 1; }
    const best = Object.keys(cnt).sort(function (a, b) { return cnt[b] - cnt[a]; })[0];
    for (const id of ids) { if (per[iso][id].t !== best) { per[iso][id].t = best; unified++; } }
  }
}
const ids = []; for (const j of jobs) { for (const x of j.ids) { if (ids.indexOf(x) === -1) { ids.push(x); } } }
const stats = {}; for (const iso in per) { const v = Object.values(per[iso]); stats[iso] = { ok: v.length, tm_exact_reused: v.filter(function (x) { return x.tm.indexOf('100%') === 0; }).length }; }
return [{ json: { per: per, bad: bad, call_errors: callErr, unified: unified, stats: stats, ids: ids.join(','), guides: jobs.reduce(function (a, j) { a[j.iso] = j.guide; return a; }, {}) } }];

// Guard: writes only into translations that are still empty right now, only if EN is unchanged. Status: unverified + AI_TO_REVIEW (29175).
// Descriptions: written first, only where the live description is empty.
// If Config carries a reviewed FINAL set, that set is written instead of the fresh model output.
const p = $('Parse and validate').first().json; const cfg = $('Config').first().json;
let PER = p.per;
if (cfg.final && Object.keys(cfg.final).length) { PER = {}; for (const iso in cfg.final) { PER[iso] = {}; for (const id in cfg.final[iso]) { PER[iso][id] = { en: cfg.final_en[id], t: cfg.final[iso][id] }; } } }
const b = $input.first().json.body || {};
if (!Array.isArray(b.keys)) { throw new Error('Guard fetch failed: ' + JSON.stringify(b).slice(0, 200)); }
const live = {};
for (const k of b.keys) { const m = {}; for (const t of (k.translations || [])) { m[t.language_iso] = typeof t.translation === 'string' ? t.translation : JSON.stringify(t.translation); } live[k.key_id] = { m: m, arch: k.is_archived, d: String(k.description || '') }; }
const out = []; const summary = {};
const dk = []; let dkept = 0;
for (const id in cfg.descs) { const L = live[id]; if (!L || L.arch) { continue; } if (L.d.trim()) { dkept++; continue; } dk.push({ key_id: Number(id), description: cfg.descs[id] }); }
summary.descriptions = { to_write: dk.length, kept_existing: dkept };
if (dk.length) { out.push({ json: { iso: 'descriptions', n: dk.length, body: JSON.stringify({ keys: dk }) } }); }
for (const iso in PER) {
  const keys = []; let skipped = 0, enChanged = 0;
  for (const id in PER[iso]) {
    const L = live[id]; if (!L || L.arch) { skipped++; continue; }
    if (String(L.m.en || '') !== PER[iso][id].en) { enChanged++; continue; }
    if (String(L.m[iso] || '').trim()) { skipped++; continue; }
    keys.push({ key_id: Number(id), translations: [{ language_iso: iso, translation: PER[iso][id].t, is_unverified: true, custom_translation_status_ids: [29175] }] });
  }
  summary[iso] = { to_write: keys.length, skipped_now_filled: skipped, en_changed: enChanged };
  if (keys.length) { out.push({ json: { iso: iso, n: keys.length, body: JSON.stringify({ keys: keys }) } }); }
}
return [{ json: { mode: cfg.mode, final_used: PER !== p.per, summary: summary, stats: p.stats, invalid: p.bad, call_errors: p.call_errors, unified: p.unified, guides: p.guides, writes: out.map(function (o) { return o.json; }) } }];

// Write gate: nothing is written in MODE 'check'.
const d = $input.first().json;
if (d.mode !== 'write') { return []; }
return d.writes.map(function (w) { return { json: w }; });
